 'regex-tester':()=>form(mount,[text('pattern','JavaScript regular expression','\\b\\w{4,}\\b','text',true),sel('flags','Flags',['g','gi','gm','gim','gu','giu'],'g'),area('input','Sample text','Make something useful. Share something wonderful.')],async v=>{need(v.pattern.length<=1000&&v.input.length<=20000,'Use a pattern up to 1,000 characters and sample text up to 20,000.');const code=`onmessage=({data})=>{try{const re=new RegExp(data.pattern,data.flags),matches=[];let m;while((m=re.exec(data.text))&&matches.length<200){matches.push({text:m[0],index:m.index,groups:m.slice(1)});if(!re.global)break;if(m[0]==='')re.lastIndex+=re.unicode&&data.text.codePointAt(re.lastIndex)>65535?2:1;}postMessage({matches});}catch(e){postMessage({error:e.message});}}`;const url=URL.createObjectURL(new Blob([code],{type:'application/javascript'}));worker=new Worker(url);URL.revokeObjectURL(url);const answer=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{worker?.terminate();worker=null;reject(Error('Pattern matching exceeded the time limit. Simplify the expression.'));},800);worker.onmessage=ev=>{clearTimeout(timer);resolve(ev.data);};worker.onerror=ev=>{clearTimeout(timer);reject(Error(ev.message||'Could not run the pattern.'));};worker.postMessage({pattern:v.pattern,flags:v.flags,text:v.input});});worker?.terminate();worker=null;if(disposed)return;need(!answer.error,answer.error);outputText(out,JSON.stringify(answer.matches,null,2),[['Matches returned',answer.matches.length],['Limit','200 matches / 800 ms']]);},{label:'Test regular expression'}),
